const states={woman:{},respondent:{}};
const pos={woman:'start',respondent:'start'};
const overviewStages=[
  {title:'Complaint submission',section:'Section 9; Central Rule 7(1), where applicable',time:'Within 3 months of the incident or last relevant incident; extension up to 3 further months may be granted with reasons recorded. Under applicable Central Rule 7(1), submit six copies with supporting documents and witness names and addresses to the competent Committee.'},
  {title:'Preliminary review, forum & confidentiality',section:'Sections 4, 6, 7, 9 and 16; Central Rule 7(4), where applicable',time:'Verify the competent IC/LC, Committee constitution, potential conflicts and complaint requirements. Explain confidentiality and record institutional undertakings (NDA), where used; an NDA is not a statutory condition for filing a complaint and must preserve lawful reporting and remedies.'},
  {title:'Voluntary conciliation, if requested',section:'Section 10',time:'Only before initiation of inquiry, at the aggrieved woman’s request. No pressure to settle; monetary settlement cannot be its basis.',guidance:[{title:'Possible non-monetary terms',text:'If freely agreed and lawful: a written apology, a non-repetition undertaking, or professional-contact boundaries. These are illustrative options, not a statutory checklist.'}]},
  {title:'Complaint copy and respondent reply',section:'Central Rule 7(2)–(3), where applicable',time:'Send complaint copy within 7 working days of receipt; respondent reply within 10 working days of receiving prescribed documents.'},
  {title:'Inquiry and hearings',section:'Section 11(1) — procedure; Section 11(4) — time limit',time:'Follow applicable service rules or the prescribed inquiry procedure. Complete the inquiry within 90 days.'},
  {title:'Witness examination & appreciation of evidence',section:'Section 11(3); Central Rule 7(4), where applicable',time:'Part of the 90-day inquiry; no separate fixed statutory deadline.'},
  {title:'Findings, representations and inquiry report',section:'Section 11(1), second proviso; Section 13(1)–(3)',time:'Where both parties are employees, hear both and share findings during the inquiry to enable representations before the Committee. Section 11(1) sets no fixed representation period. Provide the completed report to the employer / District Officer within 10 days of inquiry completion, and make it available to concerned parties.'},
  {title:'Action on recommendations',section:'Section 13(4)',time:'Employer / District Officer to act within 60 days of receipt of recommendations.'},
  {title:'Appeal and post-report rights',section:'Section 18',time:'Appeal period: 90 days from recommendations, subject to the applicable forum and service-rule pathway. The LC is not an appellate authority over the IC.'}
];
const stageExamples=[
 'An employee describes alleged unwelcome remarks, identifies the relevant dates and submits a written complaint to the competent Committee.',
 'Before scheduling hearings, the Committee checks its constitution, the appropriate forum and any member conflict, and explains confidentiality.',
 'Before inquiry starts, the woman requests conciliation and freely proposes an apology and professional-contact boundaries, without monetary settlement as the basis.',
 'After receiving the prescribed complaint documents, the respondent prepares a factual reply with supporting documents and witness details under the applicable rules.',
 'The Committee gives both sides an opportunity to be heard and records proceedings without deciding the outcome in advance.',
 'A witness describes what they personally observed. The Committee considers that account alongside messages and the parties’ explanations, rather than treating an allegation as proof.',
 'Where both parties are employees, the Committee shares findings for representations during the inquiry, considers them and prepares its reasoned report.',
 'The employer receives the recommendations, considers the action required and records implementation within the applicable statutory period.',
 'A party considering an appeal checks the competent forum and relevant dates instead of assuming the Local Committee can hear an appeal against an IC.'
];
let showAll=false;
let readingStep=0;
try{const saved=Number(localStorage.getItem('posh-reading-size'));if(Number.isInteger(saved)&&saved>=0&&saved<=2)readingStep=saved;}catch{}
function applyReadingSize(){
 document.documentElement.style.setProperty('--reading-scale',String(1+readingStep*.1));
 document.getElementById('reading-size').textContent=(100+readingStep*10)+'%';
 document.querySelector('[data-reading="smaller"]').disabled=readingStep===0;
 document.querySelector('[data-reading="larger"]').disabled=readingStep===2;
}
applyReadingSize();
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-reading]');if(!button)return;
 readingStep=button.dataset.reading==='reset'?0:Math.max(0,Math.min(2,readingStep+(button.dataset.reading==='larger'?1:-1)));
 applyReadingSize();try{localStorage.setItem('posh-reading-size',String(readingStep));}catch{}
});
const h=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const routeName=()=>location.hash.replace('#','').split('?')[0]||'home';
function setRoute(hash){if(location.hash==='#'+hash)navigate();else location.hash=hash;}
function header(title,desc,tag){return `<section class="app-heading"><div class="wrap"><div><a class="app-back" href="#home">← Back to homepage</a><small>${h(tag)}</small><h1>${h(title)}</h1><p>${h(desc)}</p></div><span class="app-mini">Public preview · No filing or upload</span></div></section>`;}
function home(){
 document.body.dataset.page='home';
 app.innerHTML=`
 <section class="hero home-hero" aria-labelledby="hero-title"><div class="hero-shell"><div class="hero-content"><span class="eyebrow">WORKPLACE SEXUAL HARASSMENT · POSH GUIDANCE</span><h1 id="hero-title">Understand POSH.<br/><em>Know your next step.</em></h1><p>Understand your rights and the IC/LC inquiry process. Free guidance and all nine inquiry stages—no account needed.</p><div class="hero-buttons"><a href="#guidance" class="btn btn-gold">Free guidance <span aria-hidden="true">→</span></a><a href="#demo" class="btn btn-outline">Inquiry stages <span aria-hidden="true">↗</span></a></div><a class="home-institutional-link" href="#institutional">For IC / LC & organisations: explore professional plans →</a><p class="hero-disclaimer">Educational guidance available now · Professional workspaces planned</p></div><div class="hero-panel home-start-panel" id="journeys" aria-label="Start free guidance"><span class="home-start-eyebrow">FREE · NO LOGIN</span><h2>What do you need<br/>help with?</h2><a class="start-choice" href="#woman"><span aria-hidden="true">01</span><div><strong>I have a workplace concern</strong><small>Understand your options and prepare a complaint.</small></div><span class="start-arrow" aria-hidden="true">→</span></a><a class="start-choice" href="#respondent"><span aria-hidden="true">02</span><div><strong>I received a complaint</strong><small>Understand the process and prepare a factual reply.</small></div><span class="start-arrow" aria-hidden="true">→</span></a><p class="home-start-note">Structured choices. No names or confidential case details requested.</p></div></div></section>
 <div class="assurance-strip home-proof-strip"><div class="wrap assurance-inner"><span>${window.NavigatorFinder.count} complete FAQs</span><span>${window.NavigatorLibrary.caseCount} source-checked judgments</span><span>Free guidance · No account</span><span>Human statutory decisions</span></div></div>
 <section class="section home-value-section" id="approach" aria-labelledby="approach-title"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">FOR IC / LC & ORGANISATIONS</span><h2 id="approach-title">More structure.<br/>Less procedural guesswork.</h2></div><p>Explore professional tools designed around a Committee’s responsibilities—from organising the record to preparing a draft that reflects its own reasoning.</p></div><div class="home-value-grid"><article><span class="home-value-number">01 / PROCESS</span><h3>See what needs attention.</h3><p>Planned workflow support brings procedural stages, dates and responsibilities into one organised view.</p></article><article><span class="home-value-number">02 / EVIDENCE</span><h3>Keep the record connected.</h3><p>Explore planned hearing records, exhibit references and allegation-wise evidence organisation.</p></article><article><span class="home-value-number">03 / REPORTING</span><h3>Make the reasoning easier to review.</h3><p>Professional and higher tiers add a planned editable report builder for the Committee to review and approve.</p></article></div><div class="home-section-action" id="institutional-preview"><a class="btn btn-dark" href="#institutional">Compare professional capabilities →</a><span>Find the scope that fits your Committee.</span></div></div></section>
 <section class="section home-process-section" id="how-it-works" aria-labelledby="works-title"><div class="wrap home-process-layout"><div><span class="eyebrow dark">EXPLORE BEFORE YOU CHOOSE</span><h2 id="works-title">See the process.<br/>Understand the next step.</h2><p>Start with the free nine-stage overview. See the relevant sections and timelines in a full overview or one stage at a time.</p><a href="#demo" class="btn btn-dark">Explore all nine stages →</a><p class="home-process-note">Free educational overview · No case details required</p></div><div class="home-process-preview"><div class="home-preview-label">A LOOK INSIDE THE FREE GUIDE</div><ol><li><span>01</span><div><strong>Complaint submission</strong><small>Understand the filing window and requirements.</small></div></li><li><span>05</span><div><strong>Inquiry and hearings</strong><small>See the procedural framework and inquiry timeline.</small></div></li><li><span>07</span><div><strong>Findings and inquiry report</strong><small>Understand representations and the report stage.</small></div></li></ol><a href="#demo">Open the free stage guide <span aria-hidden="true">↗</span></a></div></div></section>

 <section class="section home-knowledge-section" id="faq" aria-labelledby="faq-title"><div class="wrap home-knowledge-layout"><div><span class="eyebrow dark">ANSWERS WITH A SOURCE</span><h2 id="faq-title">Explore the detail.<br/>Follow the source.</h2><p>Search ${window.NavigatorFinder.count} numbered FAQs across 23 topics, read complete answers, and explore ${window.NavigatorLibrary.caseCount} verified judgments with their legal points and limits.</p><div class="home-knowledge-actions"><a class="btn btn-dark" href="#faq">Browse all ${window.NavigatorFinder.count} FAQs →</a><a class="btn btn-light" href="#faq/cases">Explore judgments</a></div></div><aside class="home-source-panel" id="law"><h3>Start with the statutory text.</h3><p>Educational guidance draws on the POSH Act and applicable rules. Service rules, facts and later case-law treatment still require review.</p><a target="_blank" rel="noreferrer" href="${h(E.SOURCES.act.uri)}">POSH Act, 2013 ↗</a><a target="_blank" rel="noreferrer" href="${h(E.SOURCES.rules.uri)}">Central POSH Rules, 2013 ↗</a><a target="_blank" rel="noreferrer" href="${h(E.SOURCES.pocso.uri)}">POCSO Act ↗</a></aside></div><div class="wrap home-community-line" id="community-intro"><div><strong>Have a general question?</strong><p>Explore the moderated community. Keep names and confidential case details out of public posts.</p></div><a class="text-link" href="#community">Visit the community →</a></div></section>
 <section class="section-small home-responsibility" id="integrity"><div class="wrap"><details class="home-privacy-details"><summary>Privacy, fairness and responsibility</summary><div class="trust-grid"><article><span class="trust-symbol" aria-hidden="true">◈</span><h3>Local public guidance</h3><p>Answers are kept temporarily in this browser session for the open page. Guidance answers are not sent to the server and are cleared on reload or reset. Community posting is a separate online feature; no analytics tracker is installed.</p></article><article><span class="trust-symbol" aria-hidden="true">⚖</span><h3>Human statutory decisions</h3><p>The platform does not determine culpability, witness credibility, bad faith, competence of the forum or the legal outcome.</p></article><article><span class="trust-symbol" aria-hidden="true">▣</span><h3>Production safeguards pending</h3><p>Authentication, case-data isolation, security review, legal sign-off and controlled storage must be verified before live institutional use.</p></article></div><div class="inline-note light"><strong>Community privacy:</strong> Submitted questions, answers and private reports are stored for moderation in the dedicated community database. Only approved posts are public. Generated aliases are not verified identities or a promise of untraceability; hosting providers may process technical logs. There are no public attachments, private messages or self-edit controls. Use the report action to flag published material or request review/removal. Retention and removal are currently handled manually; automatic deletion is not promised.</div><div class="inline-note light"><strong>Confidentiality:</strong> Section 16 protects sensitive complaint and inquiry information. Do not enter identifiable case details into an unverified public application.</div></details></div></section>
 <section class="closing-cta home-closing"><div class="wrap closing-inner"><div><span class="eyebrow">FOR A BETTER-PREPARED COMMITTEE</span><h2>Find the right level of support.</h2><p>Compare the planned capabilities, review what each plan includes, or request a demonstration for your organisation.</p></div><div><a href="#institutional" class="btn btn-gold">Explore institutional plans →</a><a href="mailto:trainings@thecosmicenergizers.com?subject=POSH%20Inquiry%20Navigator%20demonstration%20request" class="btn btn-outline">Request a demonstration</a></div></div></section>`;
}

